import CryptoKit
import Sodium
import Foundation
import Security

/// The cryptographic primitives from API contract section 1, as pure functions over
/// bytes so they can be checked against the shared test vectors
/// (vectors/v1.json, generated by Leave's server code, the same file every implementation is held to).
/// Nothing here touches the Keychain or the network; LeaveCrypto.swift does that.
///
/// Wire formats: AES-256-GCM is `nonce(12) ‖ ciphertext ‖ tag(16)`; HPKE is
/// `enc(65) ‖ ciphertext ‖ tag`; every string in the protocol is UTF-8 and every
/// binary value crossing an API is base64url without padding.
enum LeaveCryptoCore {
  enum Failure: Error, LocalizedError {
    case badKeyLength
    case badWire
    case badPublicKey
    case scalarOutOfRange
    case rsa(String)
    case grantField(String)

    var errorDescription: String? {
      switch self {
      case .badKeyLength: return "Key is not 32 bytes."
      case .badWire: return "Ciphertext is malformed."
      case .badPublicKey: return "Public key is malformed."
      case .scalarOutOfRange: return "Derived scalar is out of range."
      case .rsa(let m): return m
      case .grantField(let m): return m
      }
    }
  }

  // MARK: - Record encryption (recordAead)

  static func aad(_ recordType: String, _ recordId: String) -> Data {
    Data("leave:v1:\(recordType):\(recordId)".utf8)
  }

  /// AES-256-GCM seal. A nil nonce draws a random one (production); the vectors pass theirs.
  static func seal(key: Data, plaintext: Data, aad: Data, nonce: Data? = nil) throws -> Data {
    guard key.count == 32 else { throw Failure.badKeyLength }
    let n = try nonce.map { try AES.GCM.Nonce(data: $0) } ?? AES.GCM.Nonce()
    let box = try AES.GCM.seal(plaintext, using: SymmetricKey(data: key), nonce: n, authenticating: aad)
    return Data(n) + box.ciphertext + box.tag
  }

  static func open(key: Data, wire: Data, aad: Data) throws -> Data {
    guard key.count == 32 else { throw Failure.badKeyLength }
    guard wire.count >= 12 + 16 else { throw Failure.badWire }
    let nonce = try AES.GCM.Nonce(data: wire.prefix(12))
    let tag = wire.suffix(16)
    let ciphertext = wire.dropFirst(12).dropLast(16)
    let box = try AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag)
    return try AES.GCM.open(box, using: SymmetricKey(data: key), authenticating: aad)
  }

  // MARK: - Share wrap of a DEK (shareWrap)

  static func wrapKey(share: Data, recordId: String) -> Data {
    let k = HKDF<SHA256>.deriveKey(
      inputKeyMaterial: SymmetricKey(data: share),
      salt: Data(recordId.utf8),
      info: Data("leave:v1:dek-wrap".utf8),
      outputByteCount: 32
    )
    return k.withUnsafeBytes { Data($0) }
  }

  static func shareWrap(share: Data, recordType: String, recordId: String, dek: Data, nonce: Data? = nil) throws -> Data {
    try seal(key: wrapKey(share: share, recordId: recordId), plaintext: dek, aad: aad(recordType, recordId), nonce: nonce)
  }

  static func shareUnwrap(share: Data, recordType: String, recordId: String, wire: Data) throws -> Data {
    try open(key: wrapKey(share: share, recordId: recordId), wire: wire, aad: aad(recordType, recordId))
  }

  // MARK: - Account key (accountKey): rejection-sampled P-256 scalar

  /// P-256 group order n, big-endian.
  private static let p256Order = Data([
    0xff, 0xff, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
    0xbc, 0xe6, 0xfa, 0xad, 0xa7, 0x17, 0x9e, 0x84, 0xf3, 0xb9, 0xca, 0xc2, 0xfc, 0x63, 0x25, 0x51,
  ])

  /// 1 ≤ scalar ≤ n − 1, compared as big-endian bytes; no modular reduction.
  static func scalarInRange(_ s: Data) -> Bool {
    guard s.count == 32 else { return false }
    if s.allSatisfy({ $0 == 0 }) { return false }
    for (a, b) in zip(s, p256Order) {
      if a < b { return true }
      if a > b { return false }
    }
    return false // equal to n
  }

  static func accountScalar(share: Data, accountId: String) -> Data {
    var counter = 0
    while true {
      let candidate = HKDF<SHA256>.deriveKey(
        inputKeyMaterial: SymmetricKey(data: share),
        salt: Data("leave:v1:account-key".utf8),
        info: Data("\(accountId):\(counter)".utf8),
        outputByteCount: 32
      ).withUnsafeBytes { Data($0) }
      if scalarInRange(candidate) { return candidate }
      counter += 1
    }
  }

  static func accountSigningKey(share: Data, accountId: String) throws -> P256.Signing.PrivateKey {
    try P256.Signing.PrivateKey(rawRepresentation: accountScalar(share: share, accountId: accountId))
  }

  static func accountAgreementKey(share: Data, accountId: String) throws -> P256.KeyAgreement.PrivateKey {
    try P256.KeyAgreement.PrivateKey(rawRepresentation: accountScalar(share: share, accountId: accountId))
  }

  // MARK: - HPKE: DHKEM(P-256, HKDF-SHA256), HKDF-SHA256, AES-256-GCM, base mode

  static let hpkeSuite = HPKE.Ciphersuite.P256_SHA256_AES_GCM_256

  static func hpkeSeal(recipientSpki: Data, info: String, plaintext: Data) throws -> Data {
    let recipient = try P256.KeyAgreement.PublicKey(derRepresentation: recipientSpki)
    var sender = try HPKE.Sender(recipientKey: recipient, ciphersuite: hpkeSuite, info: Data(info.utf8))
    let ct = try sender.seal(plaintext)
    return sender.encapsulatedKey + ct
  }

  static func hpkeOpen(recipientKey: P256.KeyAgreement.PrivateKey, info: String, wire: Data) throws -> Data {
    guard wire.count > 65 + 16 else { throw Failure.badWire }
    let enc = wire.prefix(65)
    let ct = wire.dropFirst(65)
    var recipient = try HPKE.Recipient(privateKey: recipientKey, ciphersuite: hpkeSuite, info: Data(info.utf8), encapsulatedKey: enc)
    return try recipient.open(ct)
  }

  // MARK: - Session grant (grant)

  /// RSA-OAEP (SHA-256 hash and MGF1, empty label) of the 32-byte session key to the
  /// server's KMS public key (SPKI DER). Output is 384 bytes for RSA-3072.
  static func rsaSeal(serverSpki: Data, sessionKey: Data) throws -> Data {
    guard sessionKey.count == 32 else { throw Failure.badKeyLength }
    let attrs: [String: Any] = [
      kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
      kSecAttrKeyClass as String: kSecAttrKeyClassPublic,
    ]
    var error: Unmanaged<CFError>?
    guard let key = SecKeyCreateWithData(stripSpkiHeaderIfRSA(serverSpki) as CFData, attrs as CFDictionary, &error) else {
      throw Failure.rsa("Server key is malformed: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    guard let sealed = SecKeyCreateEncryptedData(key, .rsaEncryptionOAEPSHA256, sessionKey as CFData, &error) else {
      throw Failure.rsa("Could not seal the session key: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    return sealed as Data
  }

  /// Test helper: the inverse with a PKCS#8 private key (only the vectors carry one).
  static func rsaOpen(privateKeyPkcs8: Data, sealed: Data) throws -> Data {
    let attrs: [String: Any] = [
      kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
      kSecAttrKeyClass as String: kSecAttrKeyClassPrivate,
    ]
    var error: Unmanaged<CFError>?
    guard let key = SecKeyCreateWithData(stripPkcs8HeaderIfRSA(privateKeyPkcs8) as CFData, attrs as CFDictionary, &error) else {
      throw Failure.rsa("Private key is malformed: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    guard let plain = SecKeyCreateDecryptedData(key, .rsaEncryptionOAEPSHA256, sealed as CFData, &error) else {
      throw Failure.rsa("Could not open the session key: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    return plain as Data
  }

  static func grantAad(sessionId: String, recordId: String) -> Data {
    Data("leave:v1:grant:\(sessionId):\(recordId)".utf8)
  }

  static func sealDek(sessionKey: Data, sessionId: String, recordId: String, dek: Data, nonce: Data? = nil) throws -> Data {
    try seal(key: sessionKey, plaintext: dek, aad: grantAad(sessionId: sessionId, recordId: recordId), nonce: nonce)
  }

  // MARK: - Session grant v2 (grantV2, bound to the server's key version)

  private static let grantFieldChars = Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-")

  /// What a field of a v2 grant may hold: the AAD joins the fields with ':', so none may carry one.
  static func grantFieldOk(_ s: String) -> Bool {
    !s.isEmpty && s.allSatisfy { grantFieldChars.contains($0) }
  }

  /// Refuses a v2 grant before anything is sealed: a field outside the set, a use other than
  /// app or mcp, or an exp that is not a positive whole number of seconds.
  static func checkGrantV2(ticket: String, keyVersion: String, exp: Int, use: String, records: [(id: String, type: String)]) throws {
    guard grantFieldOk(ticket), grantFieldOk(keyVersion) else { throw Failure.grantField("grant_field: ticket or keyVersion") }
    guard use == "app" || use == "mcp" else { throw Failure.grantField("grant_field: use") }
    guard exp > 0 else { throw Failure.grantField("grant_field: exp") }
    for r in records where !grantFieldOk(r.id) || !grantFieldOk(r.type) {
      throw Failure.grantField("grant_field: record")
    }
  }

  /// Every field the server checks is in the AAD: a changed key version, exp, use, record type or
  /// id fails to open.
  static func grantAadV2(ticket: String, keyVersion: String, exp: Int, use: String, recordType: String, recordId: String) -> Data {
    Data("leave:v2:grant:\(ticket):\(keyVersion):\(exp):\(use):\(recordType):\(recordId)".utf8)
  }

  static func sealDekV2(sessionKey: Data, ticket: String, keyVersion: String, exp: Int, use: String, recordType: String, recordId: String, dek: Data, nonce: Data? = nil) throws -> Data {
    try seal(key: sessionKey, plaintext: dek, aad: grantAadV2(ticket: ticket, keyVersion: keyVersion, exp: exp, use: use, recordType: recordType, recordId: recordId), nonce: nonce)
  }

  /// The v2 body in its fixed key order: v, ticket, keyVersion, sealedSessionKey, exp, use, records
  /// (each id, type, sealedDek). No sessionId: the ticket carries it. The fields were checked by
  /// checkGrantV2, so none needs escaping.
  static func grantBodyV2(ticket: String, keyVersion: String, sealedSessionKey: Data, exp: Int, use: String, records: [(id: String, type: String, sealedDek: Data)]) -> String {
    let items = records.map { "{\"id\":\"\($0.id)\",\"type\":\"\($0.type)\",\"sealedDek\":\"\(base64url($0.sealedDek))\"}" }
    return "{\"v\":2,\"ticket\":\"\(ticket)\",\"keyVersion\":\"\(keyVersion)\",\"sealedSessionKey\":\"\(base64url(sealedSessionKey))\",\"exp\":\(exp),\"use\":\"\(use)\",\"records\":[\(items.joined(separator: ","))]}"
  }

  // MARK: - Signatures (signatures)

  static func verify(spki: Data, message: Data, signature: Data) throws -> Bool {
    let key = try P256.Signing.PublicKey(derRepresentation: spki)
    let sig: P256.Signing.ECDSASignature
    if signature.count == 64 {
      sig = try P256.Signing.ECDSASignature(rawRepresentation: signature)
    } else {
      sig = try P256.Signing.ECDSASignature(derRepresentation: signature)
    }
    return key.isValidSignature(sig, for: message)
  }

  // MARK: - Hashing and encoding

  static func sha256Hex(_ data: Data) -> String {
    SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
  }

  // MARK: - Recovery code (API contract, "Recovery blob")

  /// Crockford base32: no I, L, O or U, so a code read aloud or copied by hand has no look-alikes.
  static let recoveryAlphabet = Array("0123456789ABCDEFGHJKMNPQRSTVWXYZ")
  static let recoveryCodeLength = 28

  /// 28 characters, 5 bits each (140 bits), from the system's random generator.
  static func newRecoveryCode() throws -> String {
    var bytes = [UInt8](repeating: 0, count: recoveryCodeLength)
    guard SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes) == errSecSuccess else { throw Failure.badWire }
    return String(bytes.map { recoveryAlphabet[Int($0 & 0x1f)] })
  }

  /// What was typed, as the code itself: upper case, spaces and hyphens dropped, and the letters
  /// the alphabet leaves out read as the digits they are mistaken for (O as 0, I and L as 1).
  /// Nil when it isn't 28 characters of the alphabet.
  static func normalizeRecoveryCode(_ typed: String) -> String? {
    let mapped = typed.uppercased().compactMap { c -> Character? in
      switch c {
      case " ", "-", "\n", "\t": return nil
      case "O": return "0"
      case "I", "L": return "1"
      default: return c
      }
    }
    guard mapped.count == recoveryCodeLength, mapped.allSatisfy({ recoveryAlphabet.contains($0) }) else { return nil }
    return String(mapped)
  }

  /// "K7Q2 M9X4 T6W1 …": groups of four, as it is shown and written down.
  static func groupedRecoveryCode(_ code: String) -> String {
    stride(from: 0, to: code.count, by: 4).map { i in
      String(code[code.index(code.startIndex, offsetBy: i)..<code.index(code.startIndex, offsetBy: min(i + 4, code.count))])
    }.joined(separator: " ")
  }

  /// The key a recovery code locks the share with: Argon2id, 64 MiB, 3 passes, 1 lane, 32 bytes
  /// (the contract's parameters; RFC 9106's second recommended memory and passes). libsodium's
  /// crypto_pwhash, whose lane count is 1. It takes a few seconds; callers run it off the main thread.
  static func recoveryKey(code: String, salt: Data) throws -> Data {
    guard salt.count == 16,
          let key = Sodium().pwHash.hash(outputLength: 32, passwd: Array(code.utf8), salt: Array(salt), opsLimit: 3, memLimit: 64 * 1024 * 1024, alg: .Argon2ID13)
    else { throw Failure.badWire }
    return Data(key)
  }

  /// `0x01 ‖ salt(16) ‖ nonce(12) ‖ AES-256-GCM(share) ‖ tag(16)`, no associated data.
  static func sealRecovery(share: Data, code: String, salt: Data, nonce: Data) throws -> Data {
    guard share.count == 32, nonce.count == 12 else { throw Failure.badWire }
    let box = try AES.GCM.seal(share, using: SymmetricKey(data: try recoveryKey(code: code, salt: salt)), nonce: try AES.GCM.Nonce(data: nonce))
    return Data([0x01]) + salt + nonce + box.ciphertext + box.tag
  }

  /// The share inside a recovery blob. Throws when the code is wrong (the tag doesn't verify) or
  /// the blob isn't version 1 of the right length.
  static func openRecovery(blob: Data, code: String) throws -> Data {
    guard blob.count == 1 + 16 + 12 + 32 + 16, blob.first == 0x01 else { throw Failure.badWire }
    let bytes = Data(blob)  // re-based, so the offsets below start at zero
    let salt = bytes.subdata(in: 1..<17), nonce = bytes.subdata(in: 17..<29)
    let box = try AES.GCM.SealedBox(nonce: try AES.GCM.Nonce(data: nonce), ciphertext: bytes.subdata(in: 29..<61), tag: bytes.subdata(in: 61..<77))
    return try AES.GCM.open(box, using: SymmetricKey(data: try recoveryKey(code: code, salt: salt)))
  }

  /// Six digits both phones show when a new phone asks for the key: each works them out from the new phone's own key (the one the share is wrapped
  /// to, SPKI base64url) and the approval request's id. The athlete compares them, since the
  /// name alone is "iPhone" on every phone. The first four bytes of the SHA-256, as a number,
  /// modulo a million.
  ///
  /// What it covers: a phone someone else signed in on with an intercepted emailed code shows a
  /// code the athlete has no phone to match. What it doesn't: a server that swaps the key can
  /// try keys until one gives the same six digits; closing that needs a commitment step
  /// (RFC 6189), which is not built.
  static func compareCode(key: String, requestId: String) -> String {
    let digest = SHA256.hash(data: Data("leave:v1:device-compare:\(requestId):\(key)".utf8))
    let number = digest.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
    return String(format: "%06u", number % 1_000_000)
  }

  static func base64url(_ data: Data) -> String {
    data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
  }

  static func fromBase64url(_ s: String) -> Data? {
    var b = s.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
    while b.count % 4 != 0 { b.append("=") }
    return Data(base64Encoded: b)
  }

  // MARK: - Teammate key (teammate-v1.json; P3-3 4.2–4.4)
  //
  // Three things the athlete's phone and the Teammate's phone check between themselves, so the
  // server can't put another key in the Teammate's place: the pin (the key the athlete's phone
  // keeps, with a MAC under a key from the share), the Teammate's code (the QR when the two are
  // together) and six digits on a call (a commit-reveal exchange the server only relays).

  enum TeammateRefusal: String, Error {
    case pinRecord = "pin_record"
    case mac
    case pinOlder = "pin_older"
    case unpinned = "teammate_unpinned"
    case removed = "teammate_removed"
    case sasField = "sas_field"
  }

  /// `{teammateAccountId, spkiSha256, compared, how, at}`: compared by a scan or on a call,
  /// kept without comparing, or the Teammate removed (the zero hash).
  struct TeammatePinRecord: Equatable {
    let teammateAccountId: String
    let spkiSha256: String
    let compared: Bool
    let how: String
    let at: Int64
  }

  struct TeammatePin: Equatable {
    let record: TeammatePinRecord
    let mac: String
  }

  enum PinAccept: String { case accepted, same, pinOlder = "pin_older", pinRecord = "pin_record", mac }

  static let teammatePinLabel = "leave:v1:teammate-pin"
  static let teammateZeroHash = String(repeating: "A", count: 43)
  private static let crockford = Set("0123456789ABCDEFGHJKMNPQRSTVWXYZ")

  /// Each field as a 4-byte big-endian length, then its bytes.
  static func lengthPrefixed(_ fields: [Data]) -> Data {
    var out = Data()
    for f in fields {
      var n = UInt32(f.count).bigEndian
      out.append(Data(bytes: &n, count: 4))
      out.append(f)
    }
    return out
  }

  /// 26 characters of Crockford base32, upper case, first character 0–7.
  static func isUlid(_ s: String) -> Bool {
    guard s.utf8.count == 26, let first = s.first, ("0"..."7").contains(first) else { return false }
    return s.allSatisfy { crockford.contains($0) }
  }

  /// The 32 bytes of a hash written as 43 base64url characters, only in its canonical spelling.
  static func hash32(_ s: String) -> Data? {
    guard s.utf8.count == 43, s.utf8.allSatisfy({ ($0 >= 0x41 && $0 <= 0x5a) || ($0 >= 0x61 && $0 <= 0x7a) || ($0 >= 0x30 && $0 <= 0x39) || $0 == 0x2d || $0 == 0x5f }),
          let d = fromBase64url(s), d.count == 32, base64url(d) == s else { return nil }
    return d
  }

  static func teammatePinRecordValid(_ r: TeammatePinRecord) -> Bool {
    guard isUlid(r.teammateAccountId), hash32(r.spkiSha256) != nil, r.at >= 0 else { return false }
    let hows = r.compared ? ["scan", "call"] : ["none", "removed"]
    return hows.contains(r.how) && (r.how == "removed") == (r.spkiSha256 == teammateZeroHash)
  }

  static func teammatePinKey(share: Data, athleteAccountId: String) -> SymmetricKey {
    HKDF<SHA256>.deriveKey(inputKeyMaterial: SymmetricKey(data: share), salt: Data(athleteAccountId.utf8), info: Data(teammatePinLabel.utf8), outputByteCount: 32)
  }

  static func teammatePinMacInput(_ r: TeammatePinRecord) -> Data {
    lengthPrefixed([Data(teammatePinLabel.utf8), Data(r.teammateAccountId.utf8), hash32(r.spkiSha256) ?? Data(), Data((r.compared ? "true" : "false").utf8), Data(r.how.utf8), Data(String(r.at).utf8)])
  }

  static func teammatePinMac(share: Data, athleteAccountId: String, record: TeammatePinRecord) throws -> Data {
    guard teammatePinRecordValid(record) else { throw TeammateRefusal.pinRecord }
    return Data(HMAC<SHA256>.authenticationCode(for: teammatePinMacInput(record), using: teammatePinKey(share: share, athleteAccountId: athleteAccountId)))
  }

  static func verifyTeammatePin(share: Data, athleteAccountId: String, pin: TeammatePin) -> Bool {
    guard teammatePinRecordValid(pin.record), let mac = hash32(pin.mac) else { return false }
    // isValidAuthenticationCode compares in constant time.
    return HMAC<SHA256>.isValidAuthenticationCode(mac, authenticating: teammatePinMacInput(pin.record), using: teammatePinKey(share: share, athleteAccountId: athleteAccountId))
  }

  /// A pin record from its JSON text, read strictly: one flat object with exactly the five keys,
  /// strings without escapes, `compared` true or false, and `at` as a plain integer (no fraction,
  /// exponent or sign, so 1793570400.0 is refused). nil for anything else (pin_record).
  static func parseTeammatePinRecord(_ text: String) -> TeammatePinRecord? {
    let b = [UInt8](text.utf8)
    var i = 0
    func ws() { while i < b.count, [0x20, 0x09, 0x0a, 0x0d].contains(b[i]) { i += 1 } }
    func str() -> String? {
      guard i < b.count, b[i] == 0x22 else { return nil }
      i += 1
      let start = i
      while i < b.count, b[i] != 0x22 {
        if b[i] == 0x5c || b[i] < 0x20 { return nil }
        i += 1
      }
      guard i < b.count else { return nil }
      defer { i += 1 }
      return String(decoding: b[start..<i], as: UTF8.self)
    }
    var fields: [String: Any] = [:]
    ws()
    guard i < b.count, b[i] == 0x7b else { return nil }
    i += 1
    ws()
    while true {
      guard let key = str(), fields[key] == nil else { return nil }
      ws()
      guard i < b.count, b[i] == 0x3a else { return nil }
      i += 1
      ws()
      guard i < b.count else { return nil }
      if b[i] == 0x22 {
        guard let s = str() else { return nil }
        fields[key] = s
      } else if text.utf8.dropFirst(i).starts(with: "true".utf8) {
        fields[key] = true; i += 4
      } else if text.utf8.dropFirst(i).starts(with: "false".utf8) {
        fields[key] = false; i += 5
      } else {
        let start = i
        while i < b.count, (b[i] >= 0x30 && b[i] <= 0x39) || [0x2d, 0x2b, 0x2e, 0x65, 0x45].contains(b[i]) { i += 1 }
        let token = String(decoding: b[start..<i], as: UTF8.self)
        guard !token.isEmpty, token.utf8.allSatisfy({ $0 >= 0x30 && $0 <= 0x39 }), token == "0" || token.first != "0",
              token.count <= 16, let n = Int64(token), n <= 9_007_199_254_740_991 else { return nil }
        fields[key] = n
      }
      ws()
      guard i < b.count else { return nil }
      if b[i] == 0x2c { i += 1; ws(); continue }
      guard b[i] == 0x7d else { return nil }
      i += 1
      break
    }
    ws()
    guard i == b.count, fields.count == 5,
          let id = fields["teammateAccountId"] as? String, let hash = fields["spkiSha256"] as? String,
          let compared = fields["compared"] as? Bool, let how = fields["how"] as? String, let at = fields["at"] as? Int64 else { return nil }
    let r = TeammatePinRecord(teammateAccountId: id, spkiSha256: hash, compared: compared, how: how, at: at)
    return teammatePinRecordValid(r) ? r : nil
  }

  /// The record's JSON text as this phone writes it: fixed key order, `at` a plain integer.
  static func teammatePinRecordJson(_ r: TeammatePinRecord) -> String {
    "{\"teammateAccountId\":\"\(r.teammateAccountId)\",\"spkiSha256\":\"\(r.spkiSha256)\",\"compared\":\(r.compared),\"how\":\"\(r.how)\",\"at\":\(r.at)}"
  }

  /// A served pin against the newest pin this phone has seen (its cache, nil if none). A newer
  /// pin made with this share replaces the cache whatever Teammate it names; the identical pin
  /// changes nothing; any other is refused and the cache stays. The server can't clear or lower it.
  static func acceptServedTeammatePin(share: Data, athleteAccountId: String, cache: TeammatePin?, servedRecordJson: String, servedMac: String) -> (PinAccept, TeammatePin?) {
    guard let record = parseTeammatePinRecord(servedRecordJson) else { return (.pinRecord, cache) }
    let served = TeammatePin(record: record, mac: servedMac)
    guard verifyTeammatePin(share: share, athleteAccountId: athleteAccountId, pin: served) else { return (.mac, cache) }
    guard let cache else { return (.accepted, served) }
    if served == cache { return (.same, cache) }
    return served.record.at > cache.record.at ? (.accepted, served) : (.pinOlder, cache)
  }

  /// The `at` of a pin this phone writes, after fetching and verifying the server's current pin.
  static func teammatePinWriteAt(nowSeconds: Int64, newestSeenAt: Int64?) -> Int64 {
    guard let seen = newestSeenAt else { return nowSeconds }
    return max(nowSeconds, seen + 1)
  }

  /// The wrap gate, on the newest pin the phone holds. nil means the wrap may go ahead.
  static func teammateWrapRefusal(share: Data, athleteAccountId: String, pin: TeammatePin?, spki: Data) -> TeammateRefusal? {
    guard let pin, verifyTeammatePin(share: share, athleteAccountId: athleteAccountId, pin: pin) else { return .unpinned }
    if pin.record.how == "removed" { return .removed }
    guard let pinned = hash32(pin.record.spkiSha256), constantTimeEqual(pinned, Data(SHA256.hash(data: spki))) else { return .unpinned }
    return nil
  }

  static func constantTimeEqual(_ a: Data, _ b: Data) -> Bool {
    guard a.count == b.count else { return false }
    return zip(a, b).reduce(UInt8(0)) { $0 | ($1.0 ^ $1.1) } == 0
  }

  // The Teammate's code: LEAVE-TM1:<athlete>:<teammate>:<SHA-256 of the Teammate's own key>.

  static let teammateCodeVersion = "LEAVE-TM1"

  static func teammateCode(athleteAccountId: String, teammateAccountId: String, ownSpki: Data) -> String? {
    guard isUlid(athleteAccountId), isUlid(teammateAccountId) else { return nil }
    return "\(teammateCodeVersion):\(athleteAccountId):\(teammateAccountId):\(base64url(Data(SHA256.hash(data: ownSpki))))"
  }

  /// nil for a match, else the first failure in order: format, version, athlete, teammate, key.
  /// The person sees one sentence for each; the reason is for the app's own diagnostics.
  static func checkTeammateCode(_ text: String, myAccountId: String, teammateAccountId: String, receivedSpki: Data) -> String? {
    guard !text.isEmpty, text.utf8.allSatisfy({ $0 >= 0x21 && $0 <= 0x7e }) else { return "format" }
    let parts = text.split(separator: ":", omittingEmptySubsequences: false).map(String.init)
    guard parts.count == 4 else { return "format" }
    guard parts[0] == teammateCodeVersion else { return "version" }
    guard isUlid(parts[1]), isUlid(parts[2]), let h = hash32(parts[3]) else { return "format" }
    guard parts[1] == myAccountId else { return "athlete" }
    guard parts[2] == teammateAccountId else { return "teammate" }
    guard constantTimeEqual(h, Data(SHA256.hash(data: receivedSpki))) else { return "key" }
    return nil
  }

  // Six digits on a call: A commits, T answers with nT, A reveals nA, both show the digits.

  static let sasCommitLabel = "leave:v1:teammate-sas-commit"
  static let sasLabel = "leave:v1:teammate-sas"

  struct SasIds {
    let runId: String
    let athleteAccountId: String
    let teammateAccountId: String
  }

  private static func sasFields(_ ids: SasIds) throws -> [Data] {
    guard isUlid(ids.runId), isUlid(ids.athleteAccountId), isUlid(ids.teammateAccountId) else { throw TeammateRefusal.sasField }
    return [Data(ids.runId.utf8), Data(ids.athleteAccountId.utf8), Data(ids.teammateAccountId.utf8)]
  }

  static func sasCommit(ids: SasIds, teammateSpki: Data, nA: Data) throws -> Data {
    guard nA.count == 32 else { throw TeammateRefusal.sasField }
    return Data(SHA256.hash(data: lengthPrefixed([Data(sasCommitLabel.utf8)] + (try sasFields(ids)) + [teammateSpki, nA])))
  }

  /// The Teammate's phone's check of the revealed nA with its own key: false means no digits.
  static func sasOpens(ids: SasIds, ownSpki: Data, nA: Data, commitment: Data) throws -> Bool {
    let c = try sasCommit(ids: ids, teammateSpki: ownSpki, nA: nA)
    return commitment.count == 32 && constantTimeEqual(c, commitment)
  }

  /// The first 4 bytes of the hash as an unsigned big-endian number, mod 10^6, as 6 digits.
  static func sasDigits(ids: SasIds, teammateSpki: Data, nA: Data, nT: Data) throws -> (number: UInt32, digits: String) {
    guard nA.count == 32, nT.count == 32 else { throw TeammateRefusal.sasField }
    let d = SHA256.hash(data: lengthPrefixed([Data(sasLabel.utf8)] + (try sasFields(ids)) + [teammateSpki, nA, nT]))
    let n = d.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
    return (n, String(format: "%06u", n % 1_000_000))
  }

  /// "482913" → "482 913".
  static func sasLine(_ digits: String) -> String {
    "\(digits.prefix(3)) \(digits.dropFirst(3))"
  }

  // MARK: - ASN.1 helpers: Security wants PKCS#1 for RSA keys, the API sends SPKI / PKCS#8

  /// SPKI DER → PKCS#1 RSAPublicKey by unwrapping the outer SEQUENCE { AlgorithmIdentifier, BIT STRING }.
  static func stripSpkiHeaderIfRSA(_ der: Data) -> Data {
    guard let outer = asn1Sequence(der), let (_, afterAlg) = asn1Element(outer, at: 0), let (bits, _) = asn1Element(outer, at: afterAlg) else { return der }
    // bits = BIT STRING contents: first byte is the unused-bits count.
    return bits.count > 1 ? bits.dropFirst() : der
  }

  /// PKCS#8 DER → PKCS#1 RSAPrivateKey (the OCTET STRING after version and AlgorithmIdentifier).
  static func stripPkcs8HeaderIfRSA(_ der: Data) -> Data {
    guard let outer = asn1Sequence(der),
          let (_, afterVersion) = asn1Element(outer, at: 0),
          let (_, afterAlg) = asn1Element(outer, at: afterVersion),
          let (octets, _) = asn1Element(outer, at: afterAlg) else { return der }
    return octets
  }

  private static func asn1Sequence(_ der: Data) -> Data? {
    guard let (content, _) = asn1Element(der, at: 0), der.first == 0x30 else { return nil }
    return content
  }

  /// Returns the content of the TLV starting at `offset` and the offset just past it.
  private static func asn1Element(_ d: Data, at offset: Int) -> (Data, Int)? {
    let bytes = [UInt8](d)
    guard offset + 1 < bytes.count else { return nil }
    var i = offset + 1
    var length = Int(bytes[i])
    i += 1
    if length & 0x80 != 0 {
      let n = length & 0x7f
      guard i + n <= bytes.count else { return nil }
      length = 0
      for _ in 0..<n { length = (length << 8) | Int(bytes[i]); i += 1 }
    }
    guard i + length <= bytes.count else { return nil }
    return (Data(bytes[i..<(i + length)]), i + length)
  }
}
